import 'fantd/src/icon/style/index.less';
import { Icon } from 'fantd';
import React from 'react';
import ReactDOM from 'react-dom';

class Component extends React.Component {

    render() {
        return (
            <div>
                iconfont样式 增加fl 参数指定为自定义样式：<Icon type="jiazaizhong" fl spin /><br />
                antd 样式：<Icon type="loading" spin />
            </div>
        );
    }
}

ReactDOM.render(<Component />, document.getElementById('__react-content'));



